def minimumCost(source: str, target: str, original: List[str], changed: List[str], cost: List[int]):
    # Build graph: 26 nodes (a-z)
    # For each pair (original, changed), keep the minimum cost
    INF = float('inf')
    # dist[i][j] = min cost to change char i to char j
    # Use Floyd-Warshall since only 26 nodes

    # Initialize distance matrix
    dist = [[INF] * 26 for _ in range(26)]
    for i in range(26):
        dist[i][i] = 0

    # For each rule, update the minimum cost
    for orig, chg, c in zip(original, changed, cost):
        u = ord(orig) - ord('a')
        v = ord(chg) - ord('a')
        if c < dist[u][v]:
            dist[u][v] = c

    # Floyd-Warshall
    for k in range(26):
        for i in range(26):
            if dist[i][k] == INF:
                continue
            for j in range(26):
                if dist[k][j] == INF:
                    continue
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    total = 0
